#!/usr/bin/env python3
# EN: Regenerates embedded.h from sha512_consts.h, kernel.cl, ed25519_gpu.cl and english.txt.
# EN: The generated file is committed, so building needs only a C compiler.
# RU: Перегенерирует embedded.h из sha512_consts.h, kernel.cl, ed25519_gpu.cl и english.txt.
# RU: Сгенерированный файл хранится в репозитории, поэтому для сборки нужен только компилятор C.
#
# EN: The comments that this script itself writes into embedded.h stay English: that file is
# EN: generated and excluded from translation, and it is a C source consumed by the build, not
# EN: user-facing output. The kernel sources are read and written as UTF-8 so that their bilingual
# EN: EN:/RU: comments survive; embedded.h is a byte-exact copy of them, not a translated file.
# RU: Комментарии, которые пишет в embedded.h сам скрипт, остаются английскими: файл генерируется и
# RU: исключён из перевода, это исходник C для сборки, а не пользовательский вывод. Исходники ядер
# RU: читаются и пишутся в UTF-8, чтобы сохранились их двуязычные комментарии EN:/RU:; embedded.h —
# RU: их побайтовая копия, а не переводимый файл.
import hashlib, os

# EN: Work from opencl/ regardless of the current directory the script was started from.
# RU: Работаем из opencl/ независимо от того, из какого каталога запущен скрипт.
os.chdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))

words = open("english.txt", encoding="utf-8").read().split("\n")[:2048]

# EN: Normalise line endings before hashing so that a CRLF checkout still passes.
# RU: Нормализуем переводы строк перед хешированием, чтобы CRLF-копия тоже проходила проверку.
raw = open("english.txt", "rb").read().replace(b"\r\n", b"\n")

# EN: The wordlist must be the canonical BIP-0039 English list: exactly 2048 words and a known
# EN: SHA-256. Changing english.txt breaks every phrase the program produces, so fail loudly here.
# RU: Словарь должен быть каноническим английским списком BIP-0039: ровно 2048 слов и известный
# RU: SHA-256. Изменение english.txt ломает все фразы, которые создаёт программа, поэтому здесь
# RU: завершаемся с ошибкой.
assert len(words) == 2048 and hashlib.sha256(raw).hexdigest() == "2f5eed53a4727b4bf8880d8f3f199efc90e58503646d9ff8eff3a2ed3b24dbda"

src = (open("sha512_consts.h", encoding="utf-8").read() + "\n" +
       open("kernel.cl", encoding="utf-8").read() + "\n" +
       open("ed25519_gpu.cl", encoding="utf-8").read())


# EN: Encode one line of OpenCL source as a C string literal terminated by a newline.
# RU: Кодирует одну строку исходника OpenCL как строковый литерал C с завершающим переводом строки.
def cstr(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '\\n"'


out = ["// Generated by tools/embed.py from sha512_consts.h, kernel.cl, ed25519_gpu.cl and english.txt. Do not edit.",
       "#pragma once", "",
       "// OpenCL source as separate lines (MSVC limits the length of one string literal)",
       "static const char *const KERNEL_SRC[] = {"]

# EN: One array element per source line keeps each literal short enough for the MSVC limit.
# RU: Один элемент массива на строку исходника — так каждый литерал короче лимита MSVC.
out += ["    " + cstr(l) + "," for l in src.split("\n")]

out += ["};", "#define KERNEL_SRC_LINES (sizeof(KERNEL_SRC) / sizeof(KERNEL_SRC[0]))", "",
        "// BIP-0039 English wordlist (sha256 2f5eed53...dbda)", "static const char *const WORDS[2048] = {"]

# EN: Eight words per line keeps the generated header readable without making lines too long.
# RU: Восемь слов в строке — заголовок остаётся читаемым, а строки не слишком длинными.
for i in range(0, 2048, 8):
    out.append("    " + " ".join('"%s",' % w for w in words[i:i + 8]))

out += ["};", ""]

# EN: Always write LF endings: the checked-in header must not differ between Windows and Linux.
# RU: Всегда пишем переводы строк LF: файл в репозитории не должен отличаться между Windows и Linux.
# EN: UTF-8 is explicit: the kernel comment lines carry the bilingual EN:/RU: text verbatim.
# RU: UTF-8 задан явно: строки комментариев ядер несут двуязычный текст EN:/RU: дословно.
with open("embedded.h", "w", newline="\n", encoding="utf-8") as f:
    f.write("\n".join(out))

print("embedded.h:", len(src.split("\n")), "kernel lines, 2048 words")
